BEGIN;
ALTER TABLE public.tools ADD COLUMN IF NOT EXISTS runtime text NOT NULL DEFAULT 'findu';
ON CONFLICT (key) DO NOTHING;
UPDATE public.tools SET runtime='findu' WHERE key IN ('analyze_image','batch_task_add_task','batch_task_create','batch_task_delete','batch_task_get','batch_task_list','batch_task_pause','batch_task_remove_task','batch_task_rerun','batch_task_schedule_enabled','batch_task_start','batch_task_update_metadata','batch_task_update_schedule','batch_task_update_task','cancel_tool_execution','complete_asset_scan','create_asset','create_skill','delete_asset','deprecate_project_fact','get_asset','get_project_fact','get_tool_execution','get_vulnerability','list_knowledge_risk_types','list_project_facts','list_vulnerabilities','manage_webshell_add','manage_webshell_delete','manage_webshell_list','manage_webshell_test','manage_webshell_update','query_assets','record_vulnerability','restore_project_fact','search_knowledge_base','search_project_facts','update_asset','update_skill_file','upsert_project_fact','wait_tool_execution','webshell_exec','webshell_file_list','webshell_file_read','webshell_file_write') AND key NOT IN ('create_skill','update_skill_file');
COMMIT;
